import {chapters,levels} from './story.js';
import {fresh,active,complete,visible,dispatch,restore} from './engine.js';
import {defs,prop} from './art.js';
const $=id=>document.getElementById(id),KEY='button-bedtime-v3';let saved={},storageOK=true;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{storageOK=false;}
let states=levels.map((_,i)=>restore(i,saved.states?.[i]));let cleared=levels.map((_,i)=>saved.cleared?.[i]===true||complete(states[i]));
function maxOpen(){const first=cleared.findIndex(c=>!c);return first<0?29:first;}
let current=Number.isInteger(saved.current)?Math.max(0,Math.min(maxOpen(),saved.current)):0,selected=null,drag=null,sound=false,audio=null;
const scene=$('scene');
function save(){try{localStorage.setItem(KEY,JSON.stringify({current,states,cleared}));}catch{storageOK=false;}}
function say(t){$('feedback').textContent=t;}
function ping(win=false){if(!sound)return;try{audio ||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=win?784:523;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.27);}catch{}}
function heroRect(){const l=levels[current],s=states[current];let h={...l.hero};if(l.effect==='shrink'&&s.step>=1){h.w*=.7;h.h*=.7;h.y+=60;h.x+=25;}const route=l.steps.slice(0,s.step).find(r=>r.kind==='move'&&r.item==='hero');if(route){const t=l.objects.find(o=>o.id===route.target);h.x=Math.max(5,Math.min(395-h.w,t.x+t.w/2-h.w/2));h.y=Math.max(165,Math.min(510-h.h,t.y+t.h-h.h));}return h;}
function element(id,label,content,rect,extra=''){return `<g class="item ${selected===id?'chosen':''}" data-id="${id}" tabindex="0" role="button" aria-label="${label}" transform="translate(${rect.x} ${rect.y})" ${extra}><title>${label}</title>${content}</g>`;}
function draw(){const l=levels[current],s=states[current],h=heroRect();let objs=visible(s);const step=s.step;
 if(l.id===10&&step>=1)objs=objs.filter(o=>o.id!=='ice');if(l.effect==='caught'&&step>=1)objs=objs.filter(o=>o.id!=='star');if(l.effect==='night'&&step>=1)objs=objs.filter(o=>o.id!=='sun');
 if(l.layer)objs.sort((a,b)=>l.layer.indexOf(a.id)-l.layer.indexOf(b.id));
 const dim=l.dim&&!complete(s);const heroClass=complete(s)?'win-bounce':l.mood==='cold'&&step===0?'shiver':'breathe';
 let hero=element('hero','단추',`<image class="${heroClass}" href="art/button.webp" width="${h.w}" height="${h.h}" preserveAspectRatio="xMidYMid meet"/>`,h);
 let objects=objs.map(o=>{let shape=prop(o.type);let inner='';if(o.id==='glass'&&step>=1)shape=shape.replace(/opacity=".4"/g,'opacity="0"');if(l.effect==='portrait'&&o.id==='portrait')inner=`transform="rotate(${complete(s)?180:s.count*90} 60 60)"`;if(l.id===29&&o.id==='lamp'&&step===0)shape=shape.replace('<polygon ','<polygon style="fill:#6b756b" ');const cls=o.type==='star'?'sparkle':'';
 if(l.effect==='deflate'&&o.id==='balloon'&&step>=1)shape=`<g transform="translate(35 70) scale(.35 .22)">${shape}</g>`;
 if(l.effect==='spin'&&o.id==='windmill'&&step>=1)inner='class="wind-spin"';
 return element(o.id,o.label,`<svg class="prop ${cls}" width="${o.w}" height="${o.h}" viewBox="0 0 120 120" overflow="visible"><g ${inner}>${shape}</g></svg>`,o);
 }).join('');
 const moodText=complete(s)?'좋아!':l.mood==='cold'&&step===0?'추워…':l.mood==='quiet'?'쉿…':l.mood==='sleepy'?'졸려…':'?';
 let effect='';
 if((l.effect==='blanket'||l.effect==='sleep')&&step>=1)effect+=`<g pointer-events="none" transform="translate(${h.x-8} ${h.y+h.h*.64})"><svg width="${h.w+15}" height="${h.h*.42}" viewBox="0 0 120 120" preserveAspectRatio="none">${prop('blanket')}</svg></g>`;
 if(l.effect==='moonBowl'&&step>=1)effect+=`<g pointer-events="none" transform="translate(278 426) scale(.46)">${prop('moon')}</g>`;
 if(l.effect==='caught'&&step>=1)effect+=`<g pointer-events="none" transform="translate(260 335)"><svg width="100" height="125" viewBox="0 0 120 120">${prop('jarStar')}</svg></g>`;
 if(l.effect==='fall'&&step>=1)effect+=`<g pointer-events="none" transform="translate(280 437) scale(.6)">${prop('star')}</g>`;
 if(l.id===20&&step>=1)effect+=`<g pointer-events="none" transform="translate(${h.x+10} ${h.y-35})"><svg width="${h.w}" height="125" viewBox="0 0 120 120">${prop('umbrella')}</svg></g>`;
 if(l.effect==='untie'&&step>=1)effect+='<path d="M266 425q40 35 100-9" stroke="#a5b699" stroke-width="10" fill="none" pointer-events="none"/>';
 const glow=(l.dim&&complete(s))||l.id===29&&step>=2?'<ellipse cx="305" cy="385" rx="130" ry="160" fill="url(#light)" pointer-events="none"/>':'';
 const conf=complete(s)?`<g class="confetti" fill="#fff1c0" stroke="none">${Array.from({length:9},(_,i)=>`<circle cx="${100+Math.sin(i*5)*75+100}" cy="${210+i*19}" r="${i%3+2}"/>`).join('')}</g>`:'';
 const guide=l.tutorial&&step===0?l.tutorial==='drag'?'<path class="guide-arrow" d="M85 382Q108 344 146 373m-10-18 12 19-22-3" fill="none" stroke="#fff6d5" stroke-width="3" stroke-linecap="round" stroke-dasharray="5 5"/>':'<circle class="guide-arrow" cx="319" cy="304" r="38" fill="none" stroke="#fff2ba" stroke-width="2" stroke-dasharray="4 4"/>':'';
 const thought=`<g class="thought" transform="translate(${Math.min(330,h.x+h.w*.85)} ${Math.max(210,h.y-4)})"><path d="M-5 0q18-16 37-4t11 28q-18 13-32 2L0 33l1-13q-19-6-6-20Z" fill="#fff4db" stroke="#d4bf9a" stroke-width="1"/><text x="19" y="15" text-anchor="middle">${moodText}</text></g>`;
 scene.innerHTML=defs+`<g ${dim?'style="filter:brightness(.32)"':''}><image id="background" href="art/bedroom.webp" width="400" height="560" preserveAspectRatio="xMidYMid slice"/>${glow}${hero}${objects}${effect}</g>${thought}${guide}${conf}`;
 if(l.effect==='night'&&complete(s)||l.effect==='sleep'&&complete(s))scene.insertAdjacentHTML('beforeend','<rect class="night-mask" width="400" height="560" fill="#183751" opacity=".18"/>');
}
function accessible(){const l=levels[current],s=states[current],objs=[{id:'hero',label:'단추'},...visible(s)];$('accessible-objects').innerHTML=objs.map(o=>`<button data-choose="${o.id}" class="${selected===o.id?'selected':''}">${o.label}</button>`).join('');$('shift-button').hidden=!selected||active(s)?.kind!=='shift'||active(s).item!==selected;$('selection').hidden=!selected;if(selected)$('selection').textContent=`${selected==='hero'?'단추':l.objects.find(o=>o.id===selected)?.label} 선택 · 사용할 곳을 눌러요`;
}
function render(text){selected=null;const l=levels[current];$('chapter').textContent=chapters[l.chapter].title;$('total').textContent=`${cleared.filter(Boolean).length} / 30`;$('number').textContent=`STAGE ${String(l.id).padStart(2,'0')}`;$('goal').textContent=l.goal;$('continue').hidden=!complete(states[current]);$('continue').textContent=current===29?'모험 다시 둘러보기 →':'다음 단계 →';$('tutorial').hidden=!(l.tutorial&&states[current].step===0);$('tutorial').textContent=l.tutorial==='drag'?'이불을 끌어 단추에게 덮어 주세요.':'조명을 톡 눌러 보세요.';say(text||(complete(states[current])?'잘 해결했어요!':'장면 속 물건을 눌러 보세요.'));draw();accessible();save();}
function showClear(){const l=levels[current];$('clear-tag').textContent=current===29?'오늘 밤의 모험, 끝':'잘했어요!';$('clear-title').textContent=current===29?'좋은 꿈 꿔, 단추.':'해결했어요!';$('clear-copy').textContent=l.steps.at(-1).done;$('next').textContent=current===29?'30개 장면 다시 둘러보기 →':'다음 단계 →';$('clear-dialog').showModal();}
function apply(a){const r=dispatch(states[current],a);states[current]=r.state;if(r.changed){if(complete(r.state))cleared[current]=true;render(r.message);ping(r.advanced);if(r.advanced&&complete(r.state))showClear();}else{say(r.message);selected=null;draw();accessible();}}
function choose(id){const s=states[current],rule=active(s);if(!rule){say('다음 단계로 가 볼까요?');return;}if(selected){if(id===selected){selected=null;draw();accessible();return;}const item=selected;selected=null;apply({kind:'move',item,target:id});return;}
 const movement=levels[current].steps.slice(s.step).some(r=>['move','shift'].includes(r.kind)&&r.item===id);
 if(movement){selected=id;draw();accessible();say(rule.kind==='shift'&&rule.item===id?'잡고 옆으로 치워 보세요.':'사용할 곳으로 옮겨 보세요.');return;}apply({kind:'tap',item:id});}
function point(e){const p=scene.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(scene.getScreenCTM().inverse());}
function boxes(){return [{id:'hero',...heroRect()},...visible(states[current])];}
function hit(p,exclude){return boxes().reverse().find(o=>o.id!==exclude&&p.x>=o.x-5&&p.x<=o.x+o.w+5&&p.y>=o.y-5&&p.y<=o.y+o.h+5)?.id;}
scene.addEventListener('pointerdown',e=>{if(e.button!==0)return;const el=e.target.closest('[data-id]');if(!el)return;const p=point(e);drag={id:el.dataset.id,el,start:p,pointer:e.pointerId,moved:false,ghost:null,base:boxes().find(o=>o.id===el.dataset.id)};scene.setPointerCapture(e.pointerId);});
scene.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const p=point(e),dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(!drag.moved&&Math.hypot(dx,dy)<9)return;if(!drag.moved){drag.moved=true;drag.ghost=drag.el.cloneNode(true);drag.ghost.removeAttribute('data-id');drag.ghost.removeAttribute('tabindex');drag.ghost.setAttribute('aria-hidden','true');drag.ghost.style.pointerEvents='none';drag.ghost.style.opacity='.9';scene.appendChild(drag.ghost);drag.el.style.opacity='.25';}drag.ghost.setAttribute('transform',`translate(${drag.base.x+dx} ${drag.base.y+dy})`);});
scene.addEventListener('pointerup',e=>{if(!drag||drag.pointer!==e.pointerId)return;const d=drag,p=point(e);drag=null;d.ghost?.remove();d.el.style.opacity='';if(scene.hasPointerCapture(e.pointerId))scene.releasePointerCapture(e.pointerId);if(d.moved){const distance=Math.hypot(p.x-d.start.x,p.y-d.start.y),r=active(states[current]);selected=null;if(r?.kind==='shift'&&r.item===d.id)apply({kind:'shift',item:d.id,distance});else apply({kind:'move',item:d.id,target:hit(p,d.id)||''});}else choose(d.id);});
function cancelDrag(){if(!drag)return;drag.ghost?.remove();drag.el.style.opacity='';drag=null;}
scene.addEventListener('pointercancel',cancelDrag);scene.addEventListener('lostpointercapture',cancelDrag);scene.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const el=e.target.closest('[data-id]');if(el)choose(el.dataset.id);}if(e.key==='Escape'){selected=null;draw();accessible();}});
$('accessible-objects').onclick=e=>{const b=e.target.closest('[data-choose]');if(b)choose(b.dataset.choose);};$('shift-button').onclick=()=>{if(selected)apply({kind:'shift',item:selected,distance:60});};$('hint').onclick=()=>{const s=states[current],r=active(s);if(!r){say('이미 해결한 장면이에요!');return;}s.hints++;say(r.hint);save();};$('reset').onclick=()=>{cancelDrag();states[current]=fresh(current);render('처음부터 다시 살펴볼까요?');};
function next(){if(current===29){openMap();return;}if(!complete(states[current]))return;current++;render();window.scrollTo({top:0,behavior:'instant'});}
$('next').onclick=()=>{$('clear-dialog').close();next();};$('continue').onclick=next;
function openMap(){const max=maxOpen();$('map-content').innerHTML=chapters.map((c,ci)=>`<section class="map-chapter"><h3>${c.title}</h3><div class="map-nodes">${levels.filter(l=>l.chapter===ci).map(l=>`<button data-level="${l.id-1}" ${l.id-1>max?'disabled':''} class="${cleared[l.id-1]?'solved ':''}${l.id-1===current?'current':''}" aria-label="${l.id}단계 ${l.goal}${l.id-1>max?' 잠김':''}">${l.id-1>max?'·':cleared[l.id-1]?'✓':String(l.id).padStart(2,'0')}</button>`).join('')}</div></section>`).join('');$('save-note').textContent=storageOK?'이 브라우저에 진행을 자동 저장해요.':'현재 브라우저에서는 진행을 저장할 수 없어요.';$('map-dialog').showModal();}
$('map').onclick=openMap;$('home').onclick=e=>{e.preventDefault();openMap();};$('map-content').onclick=e=>{const b=e.target.closest('[data-level]');if(!b||b.disabled||Number(b.dataset.level)>maxOpen())return;current=Number(b.dataset.level);$('map-dialog').close();render();window.scrollTo({top:0,behavior:'instant'});};for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♪ ON':'♪ OFF';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'효과음 끄기':'효과음 켜기');ping();};render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
